def canonical_keys(g,surfaces,mouths):
    """Use the lower original incidence and reverse its peer's profile rank."""
    mid=c.named(g,'st_cn_mouth','INT');rank=c.named(g,'st_cn_rank','INT')
    active=c._read(g,mouths,'st_cj_seam',mid,'BOOLEAN')*_compare(g,mid,0,'GREATER_EQUAL')
    peer=c._read(g,mouths,'st_cj_seam_peer',mid,'INT')
    flip=_compare(g,peer,mid,'LESS_THAN')
    key=g.xyz(0.,c.choose(g,flip,peer,mid,'INT'),
        c.choose(g,flip,c._read(g,mouths,'st_cs_intervals',mid,'INT')-rank,rank,'INT'))
    return c._store(g,surfaces,'_bridge_key',c.choose(g,active,key,c.named(g,'_bridge_key','FLOAT_VECTOR'),'VECTOR'),'FLOAT_VECTOR')
